<script lang="ts">
 import NoteMedia from './NoteMedia.svelte';
 import {attachments,ATTACHMENTS} from '../core/attachments';
 import type {Core} from '../core/core';
 import {surface} from './surfaces';
 import {CheckpointWriter,EDITOR_CHECKPOINT,type EditorCheckpoint,type CheckpointState} from '../core/editor-checkpoint';
 import {onMount,tick} from 'svelte';
 import {formatText,type Format} from './text-edit';
 import Choice from './Choice.svelte';
 import AppearancePicker from './AppearancePicker.svelte';
 import {noteText} from './note-share';
 import RichText from './RichText.svelte';
 import DraftStatus from './DraftStatus.svelte';
 import {resolveAtom} from '../core/note-references';
 let options=$state(false),appearanceOpen=$state(false),aliasesOpen=$state(false),shareOpen=$state(false),shareMessage=$state('');
 async function share(markdown:boolean,copy=false){try{const text=noteText(draft.title||'',[draft.content||'',...attachments(draft).filter(a=>a.transcript).map(a=>'## '+a.name+'\n\n'+a.transcript)].filter(Boolean).join('\n\n'),markdown);if(!copy&&navigator.share)await navigator.share({title:draft.title||'',text});else{await navigator.clipboard.writeText(text);shareMessage='Скопировано';}}catch(e){if((e as Error).name!=='AbortError')error=(e as Error).message;}}
 let visual=$state<RichText>();let raw=$state(false);

 import type {Atom,Snapshot,AtomState} from '../core/model';
 import type {AtomType} from '../plugins/api';
 import {normalize} from '../core/core';
 import {type Candidate,type Rejection} from '../core/matching';
 import {GraphWorkerClient} from '../graph/worker-client';
 import type {Preferences} from '../core/preferences';
 import type {StorageAdapter} from '../core/model';
 let {appearanceEnabled=true,core,mediaEnabled=false,audioEnabled=false,transcriptionEnabled=false,initial,data,types,parent,prefs,section,storage,recovery,onopen,onsave,onclose,ondelete}:{appearanceEnabled?:boolean;core?:Core;mediaEnabled?:boolean;audioEnabled?:boolean;transcriptionEnabled?:boolean;initial:Partial<Atom>;data:Snapshot;types:AtomType[];parent?:string;prefs:Preferences;section:string;storage:StorageAdapter;recovery?:EditorCheckpoint;onopen:(id:string)=>void;onsave:(draft:Partial<Atom>&{title:string},add:{to:string;relation:string;source?:string}[],remove:string[],keepOpen?:boolean)=>Promise<Atom>;onclose:()=>void;ondelete:(id:string)=>Promise<void>}=$props();
 const recovered=(()=>recovery)();
 const seed=(()=>JSON.parse(JSON.stringify(initial)) as Partial<Atom>)();
 let draft=$state<Partial<Atom>>(recovered?{...$state.snapshot(recovered.draft),appearance:{...recovered.draft.appearance}}:{...seed,appearance:{...seed.appearance},aliases:[...(seed.aliases||[])]});
 let matchAtoms=$state.raw<Atom[]>([]);
 $effect(()=>{matchAtoms=$state.snapshot(data.atoms);});
 let matcher=$state<GraphWorkerClient|null>(null);let matches=$state<Candidate[]>([]);let matchVersion=0;
 let rejection=$state<Rejection|undefined>();
 let aliases=$state(recovered?.aliases??(seed.aliases||[]).join(', '));let linkQuery=$state('');let relation=$state('related');let add=$state<{to:string;relation:string;source?:string}[]>(recovered?.add||[]);let remove=$state<string[]>(recovered?.remove||[]);let saving=$state(false);let error=$state('');let checkpointState=$state<CheckpointState>('clean');let checkpointChangedAt=$state(0);let viewportHeight=$state<number|undefined>();let viewportTop=$state<number|undefined>();let confirmDelete=$state((()=>section==='delete')());let titleInput:HTMLInputElement;let form:HTMLFormElement;let textArea=$state<HTMLTextAreaElement>(null!);const mobile=matchMedia("(max-width:650px)").matches;const sizeKey=mobile?"phosphorea:editor-mobile-expanded":"phosphorea:editor-expanded";let expanded=$state((()=>{try{const saved=localStorage.getItem(sizeKey);return saved===null?mobile:saved==="true";}catch{return mobile;}})());let sheetStart=0,sheetDragged=false;function setExpanded(value:boolean){expanded=value;try{localStorage.setItem(sizeKey,String(value));}catch{}}let quickLinks=$state(false);let quickQuery=$state('');let quickInput=$state<HTMLInputElement>(null!);let selection={start:0,end:0};
 const labels:Record<AtomState,string>={normal:'Обычные',now:'Сейчас',paused:'Отложить',archived:'Архив'};
 const offeredTypes=$derived(types.filter(t=>t.id!=='task'&&t.id!=='builtin.templates:task'));
 const currentType=$derived(offeredTypes.find(t=>t.id===draft.type||t.id.startsWith('builtin.templates:')&&t.id.split(':').pop()===draft.type));
 const original=JSON.stringify({draft:seed,aliases:(seed.aliases||[]).join(', ')});
 const dirty=()=>JSON.stringify({draft:$state.snapshot(draft),aliases})!==original||add.length>0||remove.length>0;
 const linked=$derived(data.links.filter(l=>(l.from===draft.id||l.to===draft.id)&&!remove.includes(l.id)));
 const candidates=$derived.by(()=>{const excluded=new Set([draft.id||'',parent||'',...linked.flatMap(l=>[l.from,l.to]),...add.map(l=>l.to),...data.links.filter(l=>remove.includes(l.id)).flatMap(l=>[l.from,l.to])]);const q=normalize(linkQuery);if(q)return data.atoms.filter(a=>!excluded.has(a.id)&&[a.title,...a.aliases].some(t=>normalize(t).includes(q))).slice(0,6).map(atom=>({atom,confidence:1,reason:'title' as const}));if(prefs.linkMode==='off')return[];return matches.filter(c=>!excluded.has(c.atom.id)).slice(0,6);});

 $effect(()=>{const text=(draft.title||'')+' '+(draft.content||'');const atoms=matchAtoms,suppression=$state.snapshot(rejection),enabled=prefs.linkMode!=='off';const version=++matchVersion;if(!matcher||!enabled){matches=[];return;}const worker=matcher;const timer=setTimeout(()=>worker.call<Candidate[]>('match',{text,atoms,exclude:[draft.id||''],rejection:suppression}).then(result=>{if(version===matchVersion)matches=result;}).catch(e=>error=e.message),180);return()=>clearTimeout(timer);});
 const writer=(()=>new CheckpointWriter(storage,e=>error=e.message,state=>{checkpointState=state;checkpointChangedAt=Date.now();}))();
 function recoveryValue():EditorCheckpoint|null{return dirty()?{version:1,initial:seed,draft:$state.snapshot(draft),aliases,add:$state.snapshot(add),remove:$state.snapshot(remove),parent}:null;}
 // Capture large text only when the debounce fires, rather than cloning it per keystroke.
 $effect(()=>{draft.title;draft.content;draft.type;draft.state;draft.paused;JSON.stringify(draft.appearance);JSON.stringify(draft.properties);draft.importance;aliases;add.length;remove.length;writer.schedule(recoveryValue);});
 export async function checkpoint(){writer.schedule(recoveryValue);await writer.flush();}
 async function discard(){try{writer.cancel();await writer.flush();await storage.transaction([{kind:'setting',key:EDITOR_CHECKPOINT,value:null}]);onclose();return true;}catch(e){error=(e as Error).message;return false;}}
 function dismiss(){if(shareOpen)shareOpen=false;else if(appearanceOpen)appearanceOpen=false;else if(options)options=false;else if(aliasesOpen)aliasesOpen=false;else if(quickLinks)quickLinks=false;else if(confirmDelete)confirmDelete=false;else close();}
 function close(){if(saving)return;saving=true;void discard().finally(()=>saving=false);}
 async function navigate(id:string){if(!dirty()||await save())onopen(id);}
 async function format(kind:Format){await tick();if(!raw){visual?.format(kind);return;}const edit=formatText(draft.content||'',selection.start,selection.end,kind);draft.content=edit.text;await tick();textArea.focus();textArea.setSelectionRange(edit.start,edit.end);selection={start:edit.start,end:edit.end};}
 async function showLinks(){quickLinks=!quickLinks;quickQuery='';if(quickLinks){await tick();quickInput.focus();}}
 async function insertLink(atom:Atom){const target=typeof (atom.properties.vault as {path?:string})?.path==='string'?(atom.properties.vault as {path:string}).path.replace(/\.md$/i,''):atom.title;const value=`[[${target}${target!==atom.title?'|'+atom.title:''}]]`;const content=draft.content||'';if(raw)draft.content=content.slice(0,selection.start)+value+content.slice(selection.end);else{await tick();visual?.insertWiki(value,target,atom.title);}if(!linked.some(l=>l.from===atom.id||l.to===atom.id)&&!add.some(l=>l.to===atom.id))add=[...add,{to:atom.id,relation:'related',source:'markdown'}];const caret=selection.start+value.length;selection={start:caret,end:caret};quickLinks=false;await tick();if(raw){textArea.focus();textArea.setSelectionRange(caret,caret);}else visual?.focus();}
 async function edit(){await tick();if(raw)textArea?.focus();else visual?.focus();}
 function openWiki(target:string){const atom=resolveAtom(target.split('#')[0],draft as Atom,data.atoms);if(atom)void navigate(atom.id);}
 function saveInput(){return {...$state.snapshot(draft),title:(draft.title||'').trim()||Array.from((draft.content||'').trim().split('\n')[0].replace(/^[#>*\s-]+/,'')).slice(0,120).join('')||'Без названия',aliases:aliases.split(',').map(x=>x.trim()).filter(Boolean),properties:$state.snapshot(draft.properties)||{}};}
 async function save(){if(saving)return false;if(!dirty())return discard();saving=true;error='';try{
 if(!(draft.title||'').trim()&&!(draft.content||'').trim()&&!draft.id)return await discard();
 await checkpoint();writer.cancel();await onsave(saveInput(),$state.snapshot(add),$state.snapshot(remove));return true;
 }catch(e){error=(e as Error).message;return false;}finally{saving=false;}}
 let mediaPanel=$state<NoteMedia>();async function persistForMedia(){if(saving)throw Error('Дождитесь сохранения.');saving=true;try{const atom=await onsave(saveInput(),$state.snapshot(add),$state.snapshot(remove),true);draft={...atom};add=[];remove=[];await checkpoint();return atom.id;}finally{saving=false;}}
 function pasteMedia(e:ClipboardEvent){const files=e.clipboardData?.files;if(files?.length&&mediaPanel){e.preventDefault();void mediaPanel.files(files);}}
 function dropMedia(e:DragEvent){if(e.dataTransfer?.files.length&&mediaPanel){e.preventDefault();void mediaPanel.files(e.dataTransfer.files);}}
 function prepareDelete(){if(!saving)confirmDelete=true;}

 function applyType(id:string){const t=types.find(t=>t.id===id);draft.type=id.startsWith('builtin.templates:')?id.split(':').pop()!:id;if(t){draft.appearance={...draft.appearance,...t.appearance,icon:t.icon};if(!draft.content&&t.content)draft.content=t.content;}}
 function keyboard(e:KeyboardEvent){if(e.defaultPrevented)return;if((e.ctrlKey||e.metaKey)&&['b','i','k'].includes(e.key.toLowerCase())){e.preventDefault();e.stopPropagation();if(e.key.toLowerCase()==='k')showLinks();else format(e.key.toLowerCase()==='b'?'bold':'italic');return;}if(e.key==='Escape'){e.preventDefault();dismiss();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();save();}if(e.key==='Tab'){const els=[...form.querySelectorAll<HTMLElement>('button:not([disabled]),input,textarea,select,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}}
 onMount(()=>{matcher=new GraphWorkerClient();if(section==='links')options=true;if(section==='appearance')appearanceOpen=true;if(section==='text')void edit();else if(seed.id)form.focus();else titleInput.focus();if(draft.id)storage.getSetting<Rejection>('rejected:'+draft.id).then(value=>rejection=value).catch(e=>error=e.message);const transcribed=(event:Event)=>{const {note,attachment,text,beforeRevision,revision,previousTranscript}=(event as CustomEvent).detail;if(note===draft.id){if(draft.revision===beforeRevision)draft.revision=revision;draft.properties={...draft.properties,[ATTACHMENTS]:attachments(draft as Atom).map(a=>a.id===attachment&&a.transcript===previousTranscript?{...a,transcript:text}:a)};}};window.addEventListener('phosphoreya:transcribed',transcribed);const mediaSaved=(event:Event)=>{const {note,beforeRevision,revision}=(event as CustomEvent).detail;if(note===draft.id&&draft.revision===beforeRevision)draft.revision=revision;};window.addEventListener('phosphoreya:media-saved',mediaSaved);const background=()=>{if(document.hidden)void checkpoint().catch(()=>{});};const hide=()=>{void checkpoint().catch(()=>{});};document.addEventListener('visibilitychange',background);window.addEventListener('pagehide',hide);const viewport=window.visualViewport,resizeViewport=()=>{viewportHeight=viewport?.height;viewportTop=viewport?.offsetTop;};resizeViewport();viewport?.addEventListener('resize',resizeViewport);viewport?.addEventListener('scroll',resizeViewport);const unload=(e:BeforeUnloadEvent)=>{if(dirty()&&checkpointState!=='saved'){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',unload);return()=>{window.removeEventListener('phosphoreya:transcribed',transcribed);window.removeEventListener('phosphoreya:media-saved',mediaSaved);matchVersion++;matcher?.close();writer.cancel();document.removeEventListener('visibilitychange',background);window.removeEventListener('pagehide',hide);window.removeEventListener('beforeunload',unload);viewport?.removeEventListener('resize',resizeViewport);viewport?.removeEventListener('scroll',resizeViewport);};});
</script>
<div class="scrim note-scrim" style:height={viewportHeight?`${viewportHeight}px`:undefined} style:top={viewportTop!==undefined?`${viewportTop}px`:undefined} style:bottom={viewportHeight?'auto':undefined} use:surface={{close:dismiss,blocked:()=>saving}}>
 <!-- svelte-ignore a11y_no_noninteractive_element_to_interactive_role (The form is a focus-trapped editor dialog.) -->
 <form class="editor note-editor" class:expanded class:has-media={attachments(draft).length>0} tabindex="-1" bind:this={form} role="dialog" aria-modal="true" aria-label="Редактор атома" onpastecapture={pasteMedia} ondrop={dropMedia} ondragover={e=>{if(e.dataTransfer?.types.includes('Files'))e.preventDefault();}} onsubmit={e=>{e.preventDefault();save();}} onkeydown={keyboard}>
 <button type="button" class="sheet-handle" aria-label={expanded?'Свернуть карточку':'Развернуть карточку'} aria-expanded={expanded} onpointerdown={e=>{sheetDragged=false;sheetStart=e.clientY;e.currentTarget.setPointerCapture(e.pointerId);}} onpointerup={e=>{const delta=e.clientY-sheetStart;if(Math.abs(delta)>24){sheetDragged=true;setExpanded(delta<0);}}} onclick={()=>{if(!sheetDragged)setExpanded(!expanded);sheetDragged=false;}}><span></span></button>
 <div class="row note-heading"><div class="editor-shortcuts">{#if core&&(mediaEnabled||audioEnabled)}<button type="button" class="icon-button" aria-label="Прикрепить" title="Прикрепить фото, видео или звук" aria-haspopup="menu" aria-expanded="false" onclick={e=>mediaPanel?.open(e.currentTarget)}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 12 6-6a3 3 0 0 1 4 4l-8 8a4.5 4.5 0 0 1-6.4-6.4l8.5-8.5"/></svg></button>{/if}<button type="button" class="icon-button" aria-label="Поделиться заметкой" aria-expanded={shareOpen} onclick={()=>{shareOpen=!shareOpen;options=false;}}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 15V3m-4 4 4-4 4 4M7 10H4v11h16V10h-3"/></svg></button>{#if appearanceEnabled}<button type="button" class="icon-button" aria-label="Оформление" title="Оформление" aria-expanded={appearanceOpen} onclick={()=>{appearanceOpen=!appearanceOpen;aliasesOpen=false;options=false;}}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 0-4h-1a2 2 0 0 1 0-4h3a6 6 0 0 0 0-10Z"/><circle cx="7" cy="10" r=".7"/><circle cx="10" cy="6.5" r=".7"/><circle cx="15" cy="6.5" r=".7"/></svg></button>{/if}<button type="button" class="icon-button" aria-label="Другие имена" title="Другие имена" aria-expanded={aliasesOpen} onclick={()=>{aliasesOpen=!aliasesOpen;appearanceOpen=false;options=false;}}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 18 5-12 5 12M6 14h6m4-4h5m-5 4h5m-5 4h5"/></svg></button><button type="button" class="icon-button" aria-label="Меню заметки" aria-expanded={options} onclick={()=>{options=!options;shareOpen=false;}}><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg></button></div><div class="button-wrap"><button type="submit" class="primary note-save" disabled={saving||confirmDelete}>{saving?'Сохраняем…':'Готово'}</button><button type="button" class="icon-button expand-editor" aria-label={expanded?'Свернуть редактор':'Развернуть редактор'} aria-pressed={expanded} onclick={()=>setExpanded(!expanded)}>{expanded?'↙':'↗'}</button><button type="button" class="icon-button" aria-label="Отмена" title="Отмена" disabled={saving} onclick={close}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div></div>
 {#if shareOpen}<section class="note-share" aria-label="Поделиться"><strong>Поделиться заметкой</strong><div><button type="button" onclick={()=>share(false)}>Текст</button><button type="button" onclick={()=>share(true)}>Markdown</button></div><div><button type="button" onclick={()=>share(false,true)}>Копировать текст</button><button type="button" onclick={()=>share(true,true)}>Копировать Markdown</button></div><small role="status">{shareMessage}</small></section>{/if}
 {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
 <div class="note-fields" inert={saving||confirmDelete}>
 {#if options}<section class="note-options"><div class="options-heading"><strong>Связи и действия</strong><button type="button" class="icon-button" aria-label="Закрыть меню заметки" onclick={()=>options=false}>×</button></div>{#if candidates.length}<div class="inline-suggestions"><small>Связать</small>{#each candidates as c}<button type="button" class="suggestion" onclick={()=>{add=[...add,{to:c.atom.id,relation:relation.trim()||'related'}];linkQuery='';}}>+ {c.atom.title}<small>{c.confidence<1?Math.round(c.confidence*100)+'%':''}</small></button>{/each}</div>{/if}
 <details open={section==='links'} class="links-section"><summary>Связи <span class="link-count">{linked.length+add.length+(parent?1:0)}</span></summary>
 {#if parent}<p class="link-chip">↗ {data.atoms.find(a=>a.id===parent)?.title} <small>контекст</small></p>{/if}
 {#each linked as l}{@const other=data.atoms.find(a=>a.id===(l.from===draft.id?l.to:l.from))}<div class="link-chip"><span>{l.from===draft.id?'↗':'↙'} {other?.title}<small>{l.relation==='related'?'связано':l.relation}{other?.state==='archived'?' · архив':''}</small></span><button type="button" aria-label={`Удалить связь с ${other?.title}`} onclick={()=>remove=[...remove,l.id]}>×</button></div>{/each}
 {#each add as l,i}<div class="link-chip"><span>↗ {data.atoms.find(a=>a.id===l.to)?.title}<small>{l.relation==='related'?'связано':l.relation} · новая</small></span><button type="button" aria-label="Отменить новую связь" onclick={()=>add=add.filter((_,j)=>i!==j)}>×</button></div>{/each}
 <input aria-label="Связать с атомом" placeholder="Найти существующий атом…" bind:value={linkQuery}/>
 {#if linkQuery}<input aria-label="Смысл связи" placeholder="Смысл связи" bind:value={relation} maxlength="100"/>{/if}

 </details>
 <div class="note-metadata details-body">{#if draft.paused}<button type="button" onclick={()=>draft.paused=false}>Возобновить</button>{/if}


 {#if draft.id}<button type="button" class="delete-note" onclick={prepareDelete}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6m4-6v6"/></svg>Удалить заметку</button>{/if}

 </div></section>{/if}
 <input class="atom-title" bind:this={titleInput} enterkeyhint="next" onkeydown={async e=>{if(e.key==='Enter'){e.preventDefault();await edit();}}} aria-label="Название" placeholder="О чём вы думаете?" bind:value={draft.title} maxlength="500"/>
 <div class="note-toolbar"><Choice label="Тип" value={currentType?.id||draft.type||'note'} options={[...offeredTypes.map(t=>({value:t.id,label:t.name})),...(!currentType?[{value:draft.type||'note',label:draft.type==='task'||draft.type==='builtin.templates:task'?'Задача (устаревший тип)':draft.type==='hub'?'Тема':draft.type==='note'?'Заметка':'Сохранённый тип'}]:[])]} onchange={applyType}/><Choice label="Состояние" value={draft.state||'normal'} options={Object.entries(labels).filter(([s])=>s!=='paused').map(([value,label])=>({value,label}))} onchange={value=>draft.state=value as AtomState}/><div class="editor-modes" role="group" aria-label="Режим редактора"><button type="button" class="preview-toggle" aria-pressed={!raw} onclick={()=>{raw=false;void edit();}}>Обычный</button><button type="button" class="preview-toggle" aria-pressed={raw} onclick={()=>{raw=true;void edit();}}>Markdown</button></div></div>
 {#if aliasesOpen}<label class="stack">Другие имена<input aria-label="Алиасы" placeholder="Через запятую" bind:value={aliases}/></label>{/if}
 {#if appearanceOpen}<section class="editor-appearance" aria-label="Оформление заметки"><div class="importance-control"><span>Важность</span><div role="group" aria-label="Важность">{#each ['Обычная','Важная','Главная'] as name,i}<button type="button" aria-pressed={draft.importance===i} onclick={()=>{draft.importance=i;draft.appearance={...draft.appearance,size_override:undefined};}}>{name}</button>{/each}</div></div><AppearancePicker bind:value={draft.appearance!} title={draft.title||''}/></section>{/if}
 <div class="writing-tools" onpointerdown={e=>e.preventDefault()} tabindex="-1" role="toolbar" aria-label="Форматирование текста"><button type="button" aria-label="Жирный" title="Жирный · Ctrl+B" onclick={()=>format('bold')}><b>B</b></button><button type="button" aria-label="Курсив" title="Курсив · Ctrl+I" onclick={()=>format('italic')}><i>I</i></button><button type="button" aria-label="Заголовок" onclick={()=>format('heading')}>H</button><button type="button" aria-label="Список" onclick={()=>format('list')}>≡</button><button type="button" aria-label="Чек-лист" onclick={()=>format('checkbox')}>☐</button><button type="button" aria-label="Список задач" onclick={()=>format('task')}>☑</button><button type="button" aria-label="Цитата" onclick={()=>format('quote')}>❞</button><button type="button" aria-label="Код" onclick={()=>format('code')}>‹›</button><button type="button" aria-label="Таблица" onclick={()=>format('table')}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M3 14h18M11 4v16"/></svg></button></div>
 {#if quickLinks}<div class="quick-link-picker"><input bind:this={quickInput} aria-label="Быстрая связь" placeholder="Найти заметку…" bind:value={quickQuery}/>{#each data.atoms.filter(a=>a.id!==draft.id&&normalize(a.title+' '+a.aliases.join(' ')).includes(normalize(quickQuery))).slice(0,8) as atom}<button type="button" onclick={()=>insertLink(atom)}>{atom.title}</button>{/each}</div>{/if}
 {#if !raw}<RichText bind:this={visual} value={draft.content||''} onchange={content=>draft.content=content} onwiki={openWiki} disabled={saving||confirmDelete}/>{:else}<textarea bind:this={textArea} oninput={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} onselect={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} onkeyup={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} onclick={()=>selection={start:textArea.selectionStart,end:textArea.selectionEnd}} class="note-content" aria-label="Текст" placeholder="Пишите свободно…" bind:value={draft.content}></textarea>{/if}

 {#if core}<NoteMedia bind:this={mediaPanel} {core} {mediaEnabled} {audioEnabled} {transcriptionEnabled} value={attachments(draft as Atom)} onchange={value=>draft.properties={...draft.properties,[ATTACHMENTS]:value}} onpersist={persistForMedia}/>{/if}
 </div>
 {#if confirmDelete}<div class="confirm"><p>Удалить атом и его связи? Локальная копия останется в настройках.</p><button type="button" disabled={saving} onclick={async()=>{saving=true;try{writer.cancel();await writer.flush();await ondelete(draft.id!);await storage.transaction([{kind:'setting',key:EDITOR_CHECKPOINT,value:null}]);}catch(e){error=(e as Error).message;}finally{saving=false;}}}>Удалить</button><button type="button" onclick={()=>confirmDelete=false}>Отмена</button></div>{/if}
 <DraftStatus phase={checkpointState} changedAt={checkpointChangedAt}/>
 </form>
